   426|function ledgerGithubHeaders(): Record<string, string> {
   427|  return {
   428|    Authorization: `Bearer ${ledgerGithubToken()}`,
   429|    Accept: 'application/vnd.github+json',
   430|    'Content-Type': 'application/json',
   431|  };
