   302|export function parseReplyBody(value: string | null | undefined): ParsedReplyBody {
   303|  const body = value ?? '';
   304|  if (!body.startsWith(IVX_REPLY_CONTEXT_PREFIX)) {
   305|    return { replyTo: null, body };
   306|  }
   307|  const suffixIndex = body.indexOf(IVX_REPLY_CONTEXT_SUFFIX);
   308|  if (suffixIndex < 0) {
   309|    return { replyTo: null, body };
   310|  }
   311|  try {
   312|    const encoded = body.slice(IVX_REPLY_CONTEXT_PREFIX.length, suffixIndex);
   313|    const parsed = JSON.parse(decodeURIComponent(encoded)) as Partial<ChatReplyContext>;
   314|    const replyTo: ChatReplyContext = {
   315|      messageId: safeTrim(parsed.messageId),
   316|      senderLabel: safeTrim(parsed.senderLabel) || 'Original message',
   317|      previewText: safeTrim(parsed.previewText) || 'Message',
   318|    };
   319|    const visibleBody = body.slice(suffixIndex + IVX_REPLY_CONTEXT_SUFFIX.length).replace(/^\n/, '');
   320|    return replyTo.messageId ? { replyTo, body: visibleBody } : { replyTo: null, body: visibleBody };
   321|  } catch (error) {
   322|    console.log('[IVXOwnerChatRoute] Failed to parse reply context:', error instanceof Error ? error.message : 'unknown');
